export default Products;

import React, { useState, useEffect, useRef } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory } from './types';
import { MessageCircle, Send, X, Bot, ChevronUp } from 'lucide-react';

// Import GoogleGenAI SDK
import { GoogleGenAI } from "@google/genai";

// Firebase
import { db, isConfigured } from './firebaseConfig';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  addDoc,
  getDocs
} from "firebase/firestore";

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline'>(isConfigured ? 'online' : 'offline');
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [products, setProducts] = useState<Product[]>(PRODUCTS);
  const [banners, setBanners] = useState<string[]>(HERO_IMAGES);
  const [partners, setPartners] = useState<Partner[]>(PARTNERS);
  const [categories, setCategories] = useState<Category[]>(CATEGORIES.filter(c => c.id !== 'all'));
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);
  const [messages, setMessages] = useState<any[]>([]);
  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'PINDORAMA',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@pindorama.com.br',
    address: 'Av. Guilherme Ferreira, s/n, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  const [isAIChatOpen, setIsAIChatOpen] = useState(false);
  const [aiInput, setAiInput] = useState('');
  const [aiMessages, setAiMessages] = useState<{ role: 'user' | 'model', text: string, isError?: boolean }[]>([
    { role: 'model', text: 'Olá! Sou o assistente virtual da Madeireira Pindorama. Como posso ajudar com seu projeto de madeira hoje?' }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      setShowScrollTop(window.scrollY > 500);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [aiMessages, isTyping]);

  useEffect(() => {
    if (!db || !isConfigured) {
      setLoading(false);
      setDbStatus('offline');
      return;
    }

    const unsubscribers: (() => void)[] = [];

    try {
      unsubscribers.push(onSnapshot(collection(db, "products"), snap => {
        const data = snap.docs.map(d => ({ ...d.data(), id: d.id } as Product));
        if (data.length > 0) {
          setProducts(data);
        }
        setDbStatus('online');
        setLoading(false);
      }, (err) => {
        console.error("Firestore Error:", err);
        setDbStatus('offline');
        setLoading(false);
      }));

      unsubscribers.push(onSnapshot(doc(db, "settings", "main"), d => {
        if (d.exists()) setSettings(d.data() as SiteSettings);
      }));

      unsubscribers.push(onSnapshot(collection(db, "categories"), snap => {
        const data = snap.docs.map(d => ({ ...d.data(), id: d.id } as Category));
        if (data.length > 0) setCategories(data);
      }));

    } catch (e) {
      console.error("Setup Error:", e);
      setLoading(false);
      setDbStatus('offline');
    }

    return () => unsubscribers.forEach(unsub => unsub());
  }, []);

  const handleAISend = async () => {
    if (!aiInput.trim()) return;
    const text = aiInput;
    setAiInput('');
    setAiMessages(prev => [...prev, { role: 'user', text }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: text,
        config: { 
          systemInstruction: "Você é o consultor técnico especializado da Madeireira Pindorama em Uberaba, MG. Uma empresa sólida com 45 anos de mercado (desde 1979). Responda de forma elegante, profissional e amigável. Destaque nossa tradição em Uberaba. Se o cliente perguntar sobre preços, diga que temos opções variadas e convide-o para um orçamento personalizado no WhatsApp (botão flutuante na tela). Utilize termos técnicos de marcenaria (aparelhamento, viga, caibro, deck, prancha) de forma natural.",
          thinkingConfig: { thinkingBudget: 0 }
        }
      });

      const responseText = response.text || "Desculpe, tive um problema ao processar sua pergunta.";
      setAiMessages(prev => [...prev, { role: 'model', text: responseText }]);
    } catch (e: any) {
      setAiMessages(prev => [...prev, { role: 'model', text: "Nosso consultor está offline no momento. Por favor, utilize o botão de WhatsApp abaixo para falar com nossa equipe comercial!", isError: true }]);
    } finally {
      setIsTyping(false);
    }
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  if (loading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-pindorama-green text-white">
        <div className="w-20 h-20 border-4 border-amber-600 border-t-transparent rounded-full animate-spin mb-8"></div>
        <h2 className="text-2xl font-bold tracking-[0.3em] uppercase animate-pulse">Pindorama</h2>
        <p className="mt-2 text-stone-400 text-xs tracking-widest">Carregando tradição...</p>
      </div>
    );
  }

  if (isAdmin) {
    return (
      <AdminPanel 
        products={products}
        onDeleteProduct={async (id) => db && await deleteDoc(doc(db, "products", id))}
        onUpdateProduct={async (p) => db && await updateDoc(doc(db, "products", p.id), p as any)}
        onAddProduct={async (p) => {
          if (!db) return;
          const { id, ...data } = p;
          await addDoc(collection(db, "products"), data);
        }}
        categories={categories}
        onAddCategory={async (c) => db && await addDoc(collection(db, "categories"), { name: c.name })}
        onDeleteCategory={async (id) => db && await deleteDoc(doc(db, "categories", id))}
        subcategories={subcategories}
        onAddSubcategory={async (s) => db && await addDoc(collection(db, "subcategories"), s)}
        onDeleteSubcategory={async (id) => db && await deleteDoc(doc(db, "subcategories", id))}
        messages={messages}
        onDeleteMessage={(id) => db && deleteDoc(doc(db, "messages", id))}
        settings={settings}
        onUpdateSettings={async (s) => db && await setDoc(doc(db, "settings", "main"), s)}
        banners={banners}
        onUpdateBanners={async (urls) => db && await setDoc(doc(db, "site_assets", "banners"), { urls })}
        onDeleteBanner={() => {}}
        partners={partners}
        onAddPartner={async (p) => db && await addDoc(collection(db, "partners"), p)}
        onUpdatePartner={() => {}}
        onDeletePartner={async (id) => db && await deleteDoc(doc(db, "partners", id))}
        onLogout={() => setIsAdmin(false)} 
        dbStatus={dbStatus}
        onSeedData={async () => {
          if (!db) return;
          try {
            const prodsSnap = await getDocs(collection(db, "products"));
            if (prodsSnap.empty) {
              for (const p of PRODUCTS) {
                const { id, ...data } = p;
                await addDoc(collection(db, "products"), data);
              }
              for (const c of CATEGORIES.filter(x => x.id !== 'all')) {
                const { id, ...data } = c;
                await addDoc(collection(db, "categories"), data);
              }
              await setDoc(doc(db, "settings", "main"), settings);
              alert("✅ Banco de dados preenchido!");
            } else {
              alert("O banco já possui dados.");
            }
          } catch (err: any) { alert("Erro: " + err.message); }
        }}
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar onAdminClick={() => setIsAdmin(true)} onHomeClick={scrollToTop} />
      <main>
        <Hero images={banners} />
        <About />
        <Partners partners={partners} />
        <Products products={products} categories={categories} whatsapp={settings.whatsapp} />
        <Projects />
        <Testimonials />
      </main>
      <Footer settings={settings} />

      {/* Action Buttons */}
      <div className="fixed bottom-8 right-8 z-40 flex flex-col gap-4">
        {showScrollTop && (
          <button 
            onClick={scrollToTop}
            className="bg-stone-900/10 backdrop-blur-md text-stone-700 p-4 rounded-full shadow-lg hover:bg-stone-900/20 transition-all flex items-center justify-center animate-fade-in"
          >
            <ChevronUp size={24} />
          </button>
        )}
        <button 
          onClick={() => setIsAIChatOpen(!isAIChatOpen)} 
          className="bg-amber-600 text-white p-5 rounded-[1.5rem] shadow-2xl hover:bg-amber-700 transition-all hover:scale-105 flex items-center justify-center group relative border-4 border-white"
        >
          <Bot size={28} />
          <span className="absolute -top-2 -right-2 bg-red-500 w-5 h-5 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-bold animate-pulse">1</span>
        </button>
        <a 
          href={`https://wa.me/${settings.whatsapp}`} 
          target="_blank" 
          rel="noopener noreferrer" 
          className="bg-green-500 text-white p-5 rounded-[1.5rem] shadow-2xl hover:bg-green-600 transition-all hover:scale-105 flex items-center justify-center border-4 border-white"
        >
          <MessageCircle size={28} />
        </a>
      </div>

      {isAIChatOpen && (
        <div className="fixed bottom-28 right-8 z-50 w-[90vw] md:w-[400px] bg-white rounded-[2.5rem] shadow-2xl border border-stone-200 overflow-hidden flex flex-col animate-in fade-in slide-in-from-bottom-10 duration-500">
          <div className="bg-pindorama-green p-6 flex justify-between items-center text-white">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-amber-600 rounded-2xl flex items-center justify-center">
                <Bot size={24} />
              </div>
              <div>
                <h4 className="font-bold text-sm">Consultor Especialista</h4>
                <div className="flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 bg-green-400 rounded-full"></div>
                  <span className="text-[10px] text-stone-400 uppercase tracking-widest">Online agora</span>
                </div>
              </div>
            </div>
            <button onClick={() => setIsAIChatOpen(false)} className="hover:bg-white/10 p-2 rounded-full transition-colors">
              <X size={20} />
            </button>
          </div>
          <div ref={scrollRef} className="h-96 overflow-y-auto p-6 space-y-6 bg-stone-50">
            {aiMessages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-[1.5rem] text-sm leading-relaxed ${
                  m.role === 'user' ? 'bg-amber-600 text-white shadow-lg' : 'bg-white text-stone-700 shadow-sm border border-stone-200'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex items-center gap-2 text-stone-400 text-xs font-bold uppercase tracking-widest px-2">
                <div className="flex gap-1">
                  <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce"></div>
                  <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
                Processando conhecimento...
              </div>
            )}
          </div>
          <div className="p-6 bg-white border-t border-stone-100 flex gap-3">
            <input 
              type="text" 
              className="flex-1 bg-stone-100 rounded-2xl px-6 py-4 text-sm outline-none focus:ring-2 focus:ring-amber-500 transition-all" 
              value={aiInput} 
              onChange={(e) => setAiInput(e.target.value)} 
              onKeyDown={(e) => e.key === 'Enter' && handleAISend()} 
              placeholder="Qual sua dúvida sobre madeira?" 
            />
            <button 
              onClick={handleAISend} 
              className="bg-pindorama-green text-white p-4 rounded-2xl hover:bg-green-800 transition-all shadow-lg active:scale-95 disabled:opacity-50"
              disabled={!aiInput.trim() || isTyping}
            >
              <Send size={20} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

