  ImageIcon, Save, X, Database, RefreshCw, Key, ShieldCheck, Tag, 
  AlertTriangle, Youtube, Handshake, Layers, Globe, Facebook, Instagram, Code
} from 'lucide-react';
import { Product, SiteSettings, Category, Subcategory, Partner, Brand, YouTubeVideo } from '../types';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => Promise<void>;
  onUpdateProduct: (product: Product) => Promise<void>;
  onAddProduct: (product: Product) => Promise<void>;
  categories: Category[];
  onAddCategory: (category: { name: string }) => Promise<void>;
  onDeleteCategory: (id: string) => Promise<void>;
  subcategories: Subcategory[];
  onAddSubcategory: (sub: { name: string, categoryId: string }) => Promise<void>;
  onDeleteSubcategory: (id: string) => Promise<void>;
  partners: Partner[];
  onAddPartner: (p: { name: string, logo: string }) => Promise<void>;
  onDeletePartner: (id: string) => Promise<void>;
  brands: Brand[];
  onAddBrand: (b: { name: string, logo: string }) => Promise<void>;
  onDeleteBrand: (id: string) => Promise<void>;
  videos: YouTubeVideo[];
  onAddVideo: (v: { title: string, youtubeId: string }) => Promise<void>;
  onDeleteVideo: (id: string) => Promise<void>;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => Promise<void>;
  dbStatus: 'online' | 'offline';
  onSeedData: () => void;
  onLogout: () => void;
}

type Tab = 'dashboard' | 'products' | 'categories' | 'subcategories' | 'partners' | 'brands' | 'videos' | 'settings';
type DeleteType = 'product' | 'category' | 'subcategory' | 'partner' | 'brand' | 'video';

const AdminPanel: React.FC<AdminPanelProps> = (props) => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [newSub, setNewSub] = useState({ name: '', categoryId: '' });
  const [newPartner, setNewPartner] = useState({ name: '', logo: '' });
  const [newBrand, setNewBrand] = useState({ name: '', logo: '' });
  const [newVideo, setNewVideo] = useState({ title: '', youtubeId: '' });
  const [localSettings, setLocalSettings] = useState<SiteSettings>(props.settings);
  const [isSaving, setIsSaving] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<{ id: string, name: string, type: DeleteType } | null>(null);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'pindorama1979') {
      setIsAuthenticated(true);
      setLoginError(false);
    } else {
      setLoginError(true);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, callback: (url: string) => void) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => callback(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleConfirmDelete = async () => {
    if (!itemToDelete) return;
    setIsSaving(true);
    try {
      if (itemToDelete.type === 'product') await props.onDeleteProduct(itemToDelete.id);
      if (itemToDelete.type === 'category') await props.onDeleteCategory(itemToDelete.id);
      if (itemToDelete.type === 'subcategory') await props.onDeleteSubcategory(itemToDelete.id);
      if (itemToDelete.type === 'partner') await props.onDeletePartner(itemToDelete.id);
      if (itemToDelete.type === 'brand') await props.onDeleteBrand(itemToDelete.id);
      if (itemToDelete.type === 'video') await props.onDeleteVideo(itemToDelete.id);
      setItemToDelete(null);
    } finally {
      setIsSaving(false);
    }
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-pindorama-green p-4">
        <div className="bg-white p-10 rounded-[3rem] shadow-2xl w-full max-w-md text-center">
          <div className="bg-amber-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8">
            <ShieldCheck className="text-pindorama-green w-10 h-10" />
          </div>
          <h2 className="text-3xl font-bold text-pindorama-green mb-2">Painel ADM</h2>
          <form onSubmit={handleLogin} className="space-y-4 mt-8">
            <input 
              type="password" 
              placeholder="Senha de acesso"
              className="w-full px-6 py-5 bg-stone-100 rounded-2xl outline-none focus:ring-2 focus:ring-amber-500 font-bold"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            {loginError && <p className="text-red-500 text-xs font-bold">Senha incorreta.</p>}
            <button type="submit" className="w-full bg-pindorama-green text-white py-5 rounded-2xl font-bold hover:bg-green-900 transition-all">
              Entrar
            </button>
          </form>
          <button onClick={props.onLogout} className="mt-8 text-stone-400 font-bold text-sm underline">Voltar</button>
        </div>
      </div>
    );
  }

  const renderTabIcon = (tab: Tab) => {
    switch(tab) {
      case 'dashboard': return <LayoutDashboard size={20} />;
      case 'products': return <Package size={20} />;
      case 'categories': return <Tag size={20} />;
      case 'subcategories': return <Layers size={20} />;
      case 'partners': return <Handshake size={20} />;
      case 'brands': return <ShieldCheck size={20} />;
      case 'videos': return <Youtube size={20} />;
      case 'settings': return <Settings size={20} />;
    }
  };

  return (
    <div className="flex h-screen bg-stone-50 overflow-hidden">
      <aside className="w-72 bg-pindorama-green text-white flex flex-col shrink-0">
        <div className="p-10 border-b border-white/10">
          <h2 className="text-2xl font-bold tracking-tighter">PINDORAMA</h2>
          <span className="text-[10px] font-bold uppercase tracking-widest opacity-50">Administração</span>
        </div>

        <nav className="flex-1 p-6 space-y-2 overflow-y-auto">
          {(['dashboard', 'products', 'categories', 'subcategories', 'partners', 'brands', 'videos', 'settings'] as Tab[]).map((tab) => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)} 
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all font-bold text-sm capitalize ${activeTab === tab ? 'bg-amber-600 shadow-lg' : 'hover:bg-white/5 opacity-70'}`}
            >
              {renderTabIcon(tab)} {tab === 'settings' ? 'AJUSTES' : tab}
            </button>
          ))}
        </nav>

        <button onClick={props.onLogout} className="m-6 p-6 rounded-3xl bg-white/5 hover:bg-red-500/10 text-red-400 font-bold transition-all flex items-center justify-center gap-3">
          <LogOut size={20} /> Sair
        </button>
      </aside>

      <main className="flex-1 overflow-y-auto p-12 bg-wood-grain">
        <header className="flex justify-between items-center mb-12">
          <h1 className="text-4xl font-bold text-pindorama-green capitalize">{activeTab === 'settings' ? 'Ajustes Gerais' : activeTab}</h1>
          {activeTab === 'products' && (
            <button 
              onClick={() => setEditingProduct({ id: `new-${Date.now()}`, name: '', description: '', category: props.categories[0]?.id || '', image: '', price: '' })}
              className="bg-pindorama-green text-white px-8 py-4 rounded-2xl flex items-center gap-3 shadow-xl"
            >
              <Plus size={20} /> Novo Produto
            </button>
          )}
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-stone-200">
               <p className="text-stone-400 text-[10px] font-bold uppercase mb-2">Produtos</p>
               <p className="text-4xl font-black text-pindorama-green">{props.products.length}</p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-stone-200">
               <p className="text-stone-400 text-[10px] font-bold uppercase mb-2">Parceiros</p>
               <p className="text-4xl font-black text-pindorama-green">{props.partners.length}</p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-stone-200">
               <p className="text-stone-400 text-[10px] font-bold uppercase mb-2">Vídeos</p>
               <p className="text-4xl font-black text-pindorama-green">{props.videos.length}</p>
