import React, { useState, useEffect, useRef } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory, Brand, YouTubeVideo } from './types';
import { MessageCircle, Send, X, Bot, ChevronUp } from 'lucide-react';

import { GoogleGenAI } from "@google/genai";
import { supabase, isConfigured } from './supabaseConfig';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline'>(isConfigured ? 'online' : 'offline');
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [products, setProducts] = useState<Product[]>(PRODUCTS);
  const [banners, setBanners] = useState<string[]>(HERO_IMAGES);
  const [partners, setPartners] = useState<Partner[]>(PARTNERS);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [videos, setVideos] = useState<YouTubeVideo[]>([]);
  const [categories, setCategories] = useState<Category[]>(CATEGORIES.filter(c => c.id !== 'all'));
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);

  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'PINDORAMA',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@pindorama.com.br',
    address: 'Av. Guilherme Ferreira, s/n, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  const [isAIChatOpen, setIsAIChatOpen] = useState(false);
  const [aiInput, setAiInput] = useState('');
  const [aiMessages, setAiMessages] = useState<{ role: 'user' | 'model', text: string, isError?: boolean }[]>([
    { role: 'model', text: 'Olá! Sou o assistente virtual da Madeireira Pindorama. Como posso ajudar com seu projeto de madeira hoje?' }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const fetchData = async () => {
    if (!isConfigured) return;
    try {
      const { data: pData } = await supabase.from('products').select('*');
      if (pData) setProducts(pData);
      const { data: cData } = await supabase.from('categories').select('*');
      if (cData) setCategories(cData);
      const { data: sData } = await supabase.from('subcategories').select('*');
      if (sData) setSubcategories(sData);
      const { data: prtData } = await supabase.from('partners').select('*');
      if (prtData) setPartners(prtData);
      const { data: brnData } = await supabase.from('brands').select('*');
      if (brnData) setBrands(brnData);
      const { data: vData } = await supabase.from('videos').select('*');
      if (vData) setVideos(vData);
      const { data: settData } = await supabase.from('settings').select('*').single();
      if (settData) setSettings(settData);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    if (!isConfigured) setLoading(false);
  }, []);

  // CRUD Handlers - Local & Supabase
  const handleDeleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
    if (isConfigured) await supabase.from('products').delete().eq('id', id);
  };
  const handleUpdateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    if (isConfigured) await supabase.from('products').update(p).eq('id', p.id);
  };
  const handleAddProduct = async (p: Product) => {
    const n = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setProducts(prev => [n, ...prev]);
    if (isConfigured) await supabase.from('products').insert(p);
  };

  const handleAddSubcategory = async (s: { name: string, categoryId: string }) => {
    const n = { ...s, id: Math.random().toString(36).substr(2, 9) };
    setSubcategories(prev => [...prev, n]);
    if (isConfigured) await supabase.from('subcategories').insert(s);
  };
  const handleDeleteSubcategory = async (id: string) => {
    setSubcategories(prev => prev.filter(s => s.id !== id));
    if (isConfigured) await supabase.from('subcategories').delete().eq('id', id);
  };

  const handleAddPartner = async (p: { name: string, logo: string }) => {
    const n = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setPartners(prev => [...prev, n]);
    if (isConfigured) await supabase.from('partners').insert(p);
  };
  const handleDeletePartner = async (id: string) => {
    setPartners(prev => prev.filter(p => p.id !== id));
    if (isConfigured) await supabase.from('partners').delete().eq('id', id);
  };

  const handleAddBrand = async (b: { name: string, logo: string }) => {
    const n = { ...b, id: Math.random().toString(36).substr(2, 9) };
    setBrands(prev => [...prev, n]);
    if (isConfigured) await supabase.from('brands').insert(b);
  };
  const handleDeleteBrand = async (id: string) => {
    setBrands(prev => prev.filter(b => b.id !== id));
    if (isConfigured) await supabase.from('brands').delete().eq('id', id);
  };

  const handleAddVideo = async (v: { title: string, youtubeId: string }) => {
    const n = { ...v, id: Math.random().toString(36).substr(2, 9) };
    setVideos(prev => [...prev, n]);
    if (isConfigured) await supabase.from('videos').insert(v);
  };
  const handleDeleteVideo = async (id: string) => {
    setVideos(prev => prev.filter(v => v.id !== id));
    if (isConfigured) await supabase.from('videos').delete().eq('id', id);
  };

  if (loading) return null;

  if (isAdmin) {
    return (
      <AdminPanel 
        {...{ products, categories, subcategories, partners, brands, videos, settings, dbStatus }}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        onAddCategory={async (c) => setCategories(prev => [...prev, {...c, id: Math.random().toString(36)}])}
        onDeleteCategory={async (id) => setCategories(prev => prev.filter(c => c.id !== id))}
        onAddSubcategory={handleAddSubcategory}
        onDeleteSubcategory={handleDeleteSubcategory}
        onAddPartner={handleAddPartner}
        onDeletePartner={handleDeletePartner}
        onAddBrand={handleAddBrand}
        onDeleteBrand={handleDeleteBrand}
        onAddVideo={handleAddVideo}
        onDeleteVideo={handleDeleteVideo}
        onUpdateSettings={async (s) => setSettings(s)}
        onLogout={() => setIsAdmin(false)} 
        onSeedData={() => alert("Seed functionality triggered")}
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar onAdminClick={() => setIsAdmin(true)} onHomeClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} />
      <Hero images={banners} />
      <About />
      <Partners partners={partners} />
      <Products products={products} categories={categories} whatsapp={settings.whatsapp} />
      <Projects />
      <Testimonials />
      <Footer settings={settings} />
    </div>
  );
};

