                               <Youtube size={48} className="text-red-500 opacity-50 group-hover:opacity-100 transition-opacity" />
                            </div>
                            <button onClick={() => setItemToDelete({ id: v.id, name: v.title, type: 'video' })} className="absolute top-4 right-4 bg-white/20 p-3 rounded-xl hover:bg-red-500 transition-colors text-white"><Trash2 size={18} /></button>
                         </div>
                         <div className="p-8">
                            <p className="font-black text-pindorama-green leading-tight">{v.title}</p>
                            <p className="text-[10px] text-stone-400 font-bold uppercase mt-2 font-mono tracking-tighter">ID: {v.youtubeId}</p>
                         </div>
                      </div>
                   ))}
                </div>
             </div>
          )}

          {activeTab === 'settings' && (
            <div className="max-w-5xl space-y-10 pb-24">
              <div className="bg-white p-12 rounded-[3.5rem] border border-stone-200 shadow-sm relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-8 opacity-5"><Globe size={120} /></div>
                 <h3 className="text-2xl font-black text-pindorama-green mb-10 flex items-center gap-4">
                    <div className="bg-amber-100 p-3 rounded-2xl text-amber-600"><ImageIcon size={24} /></div>
                    Logo e Identidade
                 </h3>
                 <div className="flex flex-col md:flex-row gap-12 items-center">
                    <div className="w-64 h-64 bg-stone-50 rounded-[2.5rem] border-4 border-dashed border-stone-200 flex items-center justify-center overflow-hidden shadow-inner group">
                       {localSettings.logo ? <img src={localSettings.logo} className="max-w-[85%] max-h-[85%] object-contain drop-shadow-lg" /> : <ImageIcon size={64} className="text-stone-300" />}
                    </div>
                    <div className="flex-1 space-y-6">
                       <div className="p-6 bg-amber-50 rounded-2xl border border-amber-100">
                          <p className="text-sm font-bold text-amber-800 leading-relaxed">Dica: Use uma imagem com fundo transparente (PNG) para um visual profissional na Navbar.</p>
                       </div>
                       <input type="file" onChange={e => handleImageUpload(e, url => setLocalSettings({...localSettings, logo: url}))} className="block w-full text-sm text-stone-500 file:mr-6 file:py-4 file:px-8 file:rounded-2xl file:border-0 file:text-sm file:font-black file:bg-pindorama-green file:text-white hover:file:bg-green-900 cursor-pointer" />
                    </div>
                 </div>
              </div>

              <div className="bg-white p-12 rounded-[3.5rem] border border-stone-200 shadow-sm">
                 <h3 className="text-2xl font-black text-pindorama-green mb-10 flex items-center gap-4">
                    <div className="bg-amber-100 p-3 rounded-2xl text-amber-600"><Globe size={24} /></div>
                    Dados de Localização e Contato
                 </h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="md:col-span-2 space-y-3">
                       <label className="text-[10px] font-black uppercase text-stone-400 ml-2 flex items-center gap-2"><MapPin size={10} /> Endereço Completo</label>
                       <input className="w-full p-6 bg-stone-50 rounded-2xl ring-1 ring-stone-200 focus:ring-4 focus:ring-amber-500/10 outline-none font-bold" value={localSettings.address} onChange={e => setLocalSettings({...localSettings, address: e.target.value})} />
                    </div>
                    <div className="space-y-3">
                       <label className="text-[10px] font-black uppercase text-stone-400 ml-2 flex items-center gap-2"><Phone size={10} /> Telefone Fixo</label>
                       <input className="w-full p-6 bg-stone-50 rounded-2xl ring-1 ring-stone-200 focus:ring-4 focus:ring-amber-500/10 outline-none font-bold" value={localSettings.phone} onChange={e => setLocalSettings({...localSettings, phone: e.target.value})} />
                    </div>
                    <div className="space-y-3">
                       <label className="text-[10px] font-black uppercase text-stone-400 ml-2 flex items-center gap-2"><MessageSquare size={10} /> WhatsApp de Vendas</label>
                       <input className="w-full p-6 bg-stone-50 rounded-2xl ring-1 ring-stone-200 focus:ring-4 focus:ring-amber-500/10 outline-none font-bold text-green-700" value={localSettings.whatsapp} onChange={e => setLocalSettings({...localSettings, whatsapp: e.target.value})} />
                    </div>
                    <div className="md:col-span-2 space-y-3">
                       <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Email Corporativo</label>
                       <input className="w-full p-6 bg-stone-50 rounded-2xl ring-1 ring-stone-200 outline-none font-bold" value={localSettings.email} onChange={e => setLocalSettings({...localSettings, email: e.target.value})} />
                    </div>
                 </div>
              </div>

              <div className="bg-white p-12 rounded-[3.5rem] border border-stone-200 shadow-sm">
                 <h3 className="text-2xl font-black text-pindorama-green mb-10 flex items-center gap-4">
                    <div className="bg-amber-100 p-3 rounded-2xl text-amber-600"><Facebook size={24} /></div>
                    Presença Social
                 </h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-3">
                       <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Link do Facebook</label>
                       <input className="w-full p-6 bg-stone-100/50 rounded-2xl ring-1 ring-stone-200 outline-none font-medium" placeholder="https://facebook.com/..." value={localSettings.facebook} onChange={e => setLocalSettings({...localSettings, facebook: e.target.value})} />
                    </div>
                    <div className="space-y-3">
                       <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Link do Instagram</label>
                       <input className="w-full p-6 bg-stone-100/50 rounded-2xl ring-1 ring-stone-200 outline-none font-medium" placeholder="https://instagram.com/..." value={localSettings.instagram} onChange={e => setLocalSettings({...localSettings, instagram: e.target.value})} />
