                   </div>

                   <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase text-stone-400 ml-2 tracking-widest">Detalhes Técnicos / Descrição</label>
                      <textarea className="w-full p-6 bg-stone-50 rounded-3xl ring-1 ring-stone-200 outline-none h-40 resize-none font-medium leading-relaxed" placeholder="Descreva as características da madeira..." value={editingProduct.description} onChange={e => setEditingProduct({...editingProduct, description: e.target.value})} />
                   </div>

                   <div className="flex items-center gap-10 p-8 bg-stone-50 rounded-[2.5rem] border-4 border-dashed border-stone-200">
                      <div className="w-32 h-32 bg-white rounded-3xl overflow-hidden shadow-2xl flex items-center justify-center shrink-0 border border-stone-100">
