                      </div>
                      <div className="flex-1 space-y-4">
                         <p className="text-xs font-black text-pindorama-green uppercase tracking-widest">Foto de Destaque</p>
                         <input type="file" onChange={e => handleImageUpload(e, url => setEditingProduct({...editingProduct, image: url}))} className="text-xs font-bold block w-full file:mr-4 file:py-3 file:px-6 file:rounded-xl file:border-0 file:bg-amber-600 file:text-white" />
                      </div>
                   </div>

                   <button onClick={() => props.onUpdateProduct(editingProduct).then(() => setEditingProduct(null))} className="w-full bg-amber-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl hover:bg-amber-700 transition-all flex items-center justify-center gap-4">
                      <Save size={28} /> Confirmar Cadastro
                   </button>
                </div>
              </div>
            </div>
          )}

          {/* Delete Confirmation Modal */}
          {itemToDelete && (
            <div className="fixed inset-0 bg-stone-900/90 backdrop-blur-md z-[110] flex items-center justify-center p-6">
              <div className="bg-white rounded-[3.5rem] w-full max-w-md shadow-2xl p-12 text-center transform animate-in slide-in-from-bottom-10 duration-200">
                <div className="bg-red-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 text-red-500 shadow-inner">
                   <AlertTriangle size={48} />
                </div>
                <h3 className="text-3xl font-black text-pindorama-green mb-4 leading-tight">Remover este item para sempre?</h3>
                <p className="text-stone-500 mb-10 font-medium leading-relaxed italic">Você está excluindo "{itemToDelete.name}". Esta ação é irreversível no servidor.</p>
                <div className="flex flex-col gap-3">
                  <button onClick={handleConfirmDelete} className="w-full bg-red-500 text-white py-6 rounded-2xl font-black text-lg shadow-xl hover:bg-red-600 transition-all active:scale-95">SIM, REMOVER AGORA</button>
                  <button onClick={() => setItemToDelete(null)} className="w-full bg-stone-100 text-stone-400 py-6 rounded-2xl font-black text-lg hover:bg-stone-200 transition-all">CANCELAR E MANTER</button>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

