                  <input type="text" value={editingProduct.price || ''} onChange={e => setEditingProduct({...editingProduct, price: e.target.value})} className="w-full px-8 py-4 bg-stone-50 rounded-2xl font-bold" placeholder="Ex: R$ 85,00/m" />
