import React, { useState, useRef } from 'react';
import { 
  LayoutDashboard, Package, Settings, LogOut, Plus, Trash2, Edit2, 
  ImageIcon, Save, X, Database, RefreshCw, Key, ShieldCheck, Tag, 
  Youtube, Handshake, Briefcase, Camera, Upload, Image as ImageIconLucide,
  CheckCircle, XCircle, Terminal, Loader2
} from 'lucide-react';
import { Product, SiteSettings, Category, Subcategory, Partner, Brand, YouTubeVideo, Project } from '../types';
import { supabase } from '../supabaseConfig';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => Promise<void>;
  onUpdateProduct: (product: Product) => Promise<void>;
  onAddProduct: (product: Product) => Promise<void>;
  categories: Category[];
  onAddCategory: (category: { name: string }) => Promise<void>;
  onDeleteCategory: (id: string) => Promise<void>;
  partners: Partner[];
  onAddPartner: (p: { name: string, logo: string }) => Promise<void>;
  onDeletePartner: (id: string) => Promise<void>;
  projects: Project[];
  onAddProject: (p: { title: string, location: string, image: string }) => Promise<void>;
  onDeleteProject: (id: string) => Promise<void>;
  banners: string[];
  onAddBanner: (url: string) => Promise<void>;
  onDeleteBanner: (url: string) => Promise<void>;
  videos: YouTubeVideo[];
  onAddVideo: (v: { title: string, youtubeId: string }) => Promise<void>;
  onDeleteVideo: (id: string) => Promise<void>;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => Promise<void>;
  dbStatus: 'online' | 'offline' | 'error';
  dbError?: string | null;
  onLogout: () => void;
  // Unused but required
  subcategories: Subcategory[];
  onAddSubcategory: (sub: { name: string, categoryId: string }) => Promise<void>;
  onDeleteSubcategory: (id: string) => Promise<void>;
  brands: Brand[];
  onAddBrand: (b: { name: string, logo: string }) => Promise<void>;
  onDeleteBrand: (id: string) => Promise<void>;
}

type Tab = 'dashboard' | 'products' | 'categories' | 'projects' | 'banners' | 'partners' | 'videos' | 'settings';

const AdminPanel: React.FC<AdminPanelProps> = (props) => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings>(props.settings);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<{ id: string, name: string, type: string } | null>(null);

  const [newCatName, setNewCatName] = useState('');
  const [newPartner, setNewPartner] = useState({ name: '', logo: '' });
  const [newProject, setNewProject] = useState({ title: '', location: '', image: '' });
  const [newBannerUrl, setNewBannerUrl] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Função mestre de Upload
  const uploadToSupabase = async (file: File): Promise<string | null> => {
    try {
      setIsUploading(true);
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random().toString(36).substring(2)}-${Date.now()}.${fileExt}`;
      const filePath = `uploads/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('images')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('images').getPublicUrl(filePath);
      return data.publicUrl;
    } catch (error) {
      console.error('Erro no upload:', error);
      alert('Erro ao subir imagem. Verifique se o bucket "images" foi criado e está público no Supabase.');
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'pindorama1979') {
      setIsAuthenticated(true);
      setLoginError(false);
    } else {
      setLoginError(true);
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'Início', icon: <LayoutDashboard size={20} /> },
    { id: 'products', label: 'Produtos', icon: <Package size={20} /> },
    { id: 'categories', label: 'Categorias', icon: <Tag size={20} /> },
    { id: 'banners', label: 'Banners Topo', icon: <ImageIcon size={20} /> },
    { id: 'projects', label: 'Obras/Projetos', icon: <Briefcase size={20} /> },
    { id: 'partners', label: 'Parceiros', icon: <Handshake size={20} /> },
    { id: 'settings', label: 'Ajustes Site', icon: <Settings size={20} />, highlight: true },
  ];

  const status = props.dbStatus === 'online' 
    ? { color: 'text-green-400', bg: 'bg-green-500/10', text: 'Sincronizado', icon: <CheckCircle size={14} /> }
    : { color: 'text-stone-400', bg: 'bg-stone-500/10', text: 'Offline', icon: <Database size={14} /> };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-pindorama-green p-4">
        <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl w-full max-w-md text-center border-8 border-stone-50">
          <div className="bg-amber-100 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-inner">
            <ShieldCheck className="text-pindorama-green w-12 h-12" />
          </div>
          <h2 className="text-3xl font-bold text-pindorama-green mb-2 tracking-tight uppercase">Acesso ADM</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              type="password" 
              placeholder="Senha"
              className="w-full px-8 py-6 bg-stone-100 rounded-2xl outline-none text-center text-xl font-bold"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoFocus
            />
            {loginError && <p className="text-red-500 text-xs font-bold">Senha incorreta!</p>}
            <button type="submit" className="w-full bg-pindorama-green text-white py-6 rounded-2xl font-black shadow-xl">ENTRAR</button>
          </form>
          <button onClick={props.onLogout} className="mt-8 text-stone-400 font-bold underline">Voltar para o Site</button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans">
      <aside className="w-80 bg-pindorama-green text-white flex flex-col shrink-0 shadow-2xl">
        <div className="p-10 border-b border-white/5">
           <h2 className="text-2xl font-black uppercase italic tracking-tighter mb-4">Pindorama</h2>
           <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${status.bg} ${status.color}`}>
              <div className={`w-2 h-2 rounded-full ${props.dbStatus === 'online' ? 'bg-green-400' : 'bg-stone-500'}`}></div>
              {status.text}
           </div>
        </div>
        <nav className="flex-1 p-6 space-y-1">
          {menuItems.map((item) => (
            <button 
              key={item.id}
              onClick={() => setActiveTab(item.id as Tab)} 
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all font-bold ${activeTab === item.id ? (item.highlight ? 'bg-amber-600' : 'bg-white/10') : 'hover:bg-white/5 opacity-60'}`}
            >
              {item.icon} {item.label}
            </button>
          ))}
        </nav>
        <div className="p-6">
          <button onClick={props.onLogout} className="w-full p-4 rounded-xl bg-red-500/10 text-red-400 font-bold">Logout</button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-12 bg-wood-grain">
        <div className="max-w-6xl mx-auto">
          <h1 className="text-5xl font-black text-pindorama-green uppercase italic mb-12">
            {menuItems.find(m => m.id === activeTab)?.label}
          </h1>

          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
               <div className="bg-white p-10 rounded-[3rem] shadow-sm">
                  <Package size={32} className="text-amber-600 mb-6" />
