                  </div>
               </div>
               <div className="mt-12 pt-12 border-t border-stone-100 flex justify-end">
                  <button onClick={() => { setIsSaving(true); props.onUpdateSettings(localSettings).then(() => setIsSaving(false)); }} className="bg-pindorama-green text-white px-12 py-5 rounded-2xl font-black shadow-2xl flex items-center gap-4">
