              <input type="text" placeholder="Preço" value={editingProduct.price || ''} onChange={e => setEditingProduct({...editingProduct, price: e.target.value})} className="w-full px-8 py-4 bg-stone-50 rounded-2xl font-bold" />
              <select value={editingProduct.category} onChange={e => setEditingProduct({...editingProduct, category: e.target.value})} className="w-full px-8 py-4 bg-stone-50 rounded-2xl font-bold">
                {props.categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
              </select>

              <div className="flex flex-col items-center gap-4">
                {editingProduct.image && <img src={editingProduct.image} className="w-32 h-32 rounded-2xl object-cover shadow-lg border-4 border-white" />}
                <label className="w-full">
                   <div className="w-full px-8 py-6 border-2 border-dashed border-stone-200 rounded-2xl flex items-center justify-center gap-3 cursor-pointer hover:bg-stone-50 transition-all font-bold text-stone-400 uppercase">
                      {isUploading ? <Loader2 className="animate-spin text-amber-600" /> : <><Upload size={20} /> Alterar Imagem</>}
                   </div>
                   <input type="file" className="hidden" accept="image/*" onChange={async e => {
                      const file = e.target.files?.[0];
                      if (file) {
                        const url = await uploadToSupabase(file);
                        if (url) setEditingProduct({...editingProduct, image: url});
                      }
                   }} />
                </label>
              </div>

              <textarea placeholder="Descrição" rows={4} value={editingProduct.description} onChange={e => setEditingProduct({...editingProduct, description: e.target.value})} className="w-full px-8 py-4 bg-stone-50 rounded-2xl font-bold" />
              <button 
                disabled={isUploading}
                onClick={() => { editingProduct.id.startsWith('new-') ? props.onAddProduct(editingProduct) : props.onUpdateProduct(editingProduct); setEditingProduct(null); }} 
                className="w-full bg-pindorama-green text-white py-6 rounded-2xl font-black text-lg shadow-xl"
              >
                SALVAR NO BANCO
              </button>
              <button onClick={() => setEditingProduct(null)} className="w-full text-stone-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Deletar */}
      {itemToDelete && (
        <div className="fixed inset-0 bg-stone-900/90 backdrop-blur-md z-[120] flex items-center justify-center p-6">
          <div className="bg-white rounded-[3.5rem] w-full max-w-md shadow-2xl p-12 text-center">
            <h3 className="text-3xl font-black text-pindorama-green mb-10">Excluir Permanentes?</h3>
