              <button onClick={() => { if(itemToDelete.type === 'product') props.onDeleteProduct(itemToDelete.id); setItemToDelete(null); }} className="w-full bg-red-500 text-white py-6 rounded-2xl font-black text-lg">SIM, EXCLUIR</button>
