  // Pega o ID do projeto da URL para mostrar ao usuário
  const projectId = "qdigphmrabgzlbmvqqet";

  const diagnoseStorage = async () => {
    try {
      const { data, error } = await supabase.storage.listBuckets();
      if (error) {
        if (error.message.includes("not allowed") || error.message.includes("403")) {
          return "CONEXÃO ATIVA: O Supabase proibiu listar os buckets por segurança, mas o upload pode funcionar se você criou a POLICY correta.";
        }
        throw error;
      }
      const names = data?.map(b => b.name) || [];
      if (!names.includes('images')) {
        return `ALERTA: O bucket 'images' não aparece na lista oficial. Buckets detectados: ${names.join(', ') || 'Nenhum'}.`;
      }
      return "STORAGE OK: Bucket 'images' identificado com sucesso!";
    } catch (e: any) {
      return `ERRO DE CONEXÃO: ${e.message}. Verifique sua internet e as chaves do projeto.`;
    }
  };

  const uploadToSupabase = async (file: File): Promise<string | null> => {
    try {
      setIsUploading(true);
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random().toString(36).substring(2)}-${Date.now()}.${fileExt}`;
      const filePath = `uploads/${fileName}`;

      // Tenta o upload direto sem checar se o bucket existe (bypass no erro de listagem)
      const { error: uploadError } = await supabase.storage
        .from('images')
        .upload(filePath, file);

      if (uploadError) {
        console.error("Erro no upload:", uploadError);
        alert(`FALHA NO ENVIO: ${uploadError.message}\n\nMotivos comuns:\n1. Você não criou o bucket 'images' (minúsculo).\n2. Você não criou a POLICY de permissão no menu Storage > Policies.\n3. Você está no projeto do Supabase errado.`);
        throw uploadError;
      }

      const { data } = supabase.storage.from('images').getPublicUrl(filePath);
      return data.publicUrl;
    } catch (error) {
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'pindorama1979') {
