import React, { useState, useRef } from 'react';
import { 
  LayoutDashboard, Package, Settings, LogOut, Plus, Trash2, Edit2, 
  ImageIcon, Save, X, Database, RefreshCw, Key, ShieldCheck, Tag, 
  Youtube, Handshake, Briefcase, Camera, Upload, Image as ImageIconLucide,
  CheckCircle, XCircle, Terminal, Loader2, Globe, AlertTriangle, Link2, Beaker
} from 'lucide-react';
import { Product, SiteSettings, Category, Subcategory, Partner, Brand, YouTubeVideo, Project } from '../types';
import { supabase } from '../supabaseConfig';

interface AdminPanelProps {
  products: Product[];
  onDeleteProduct: (id: string) => Promise<void>;
  onUpdateProduct: (product: Product) => Promise<void>;
  onAddProduct: (product: Product) => Promise<void>;
  categories: Category[];
  onAddCategory: (category: { name: string }) => Promise<void>;
  onDeleteCategory: (id: string) => Promise<void>;
  partners: Partner[];
  onAddPartner: (p: { name: string, logo: string }) => Promise<void>;
  onDeletePartner: (id: string) => Promise<void>;
  projects: Project[];
  onAddProject: (p: { title: string, location: string, image: string }) => Promise<void>;
  onDeleteProject: (id: string) => Promise<void>;
  banners: string[];
  onAddBanner: (url: string) => Promise<void>;
  onDeleteBanner: (url: string) => Promise<void>;
  videos: YouTubeVideo[];
  onAddVideo: (v: { title: string, youtubeId: string }) => Promise<void>;
  onDeleteVideo: (id: string) => Promise<void>;
  settings: SiteSettings;
  onUpdateSettings: (settings: SiteSettings) => Promise<void>;
  dbStatus: 'online' | 'offline' | 'error';
  dbError?: string | null;
  onLogout: () => void;
  subcategories: Subcategory[];
  onAddSubcategory: (sub: { name: string, categoryId: string }) => Promise<void>;
  onDeleteSubcategory: (id: string) => Promise<void>;
  brands: Brand[];
  onAddBrand: (b: { name: string, logo: string }) => Promise<void>;
  onDeleteBrand: (id: string) => Promise<void>;
}

type Tab = 'dashboard' | 'products' | 'categories' | 'projects' | 'banners' | 'partners' | 'settings';

const AdminPanel: React.FC<AdminPanelProps> = (props) => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings>(props.settings);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);

  const [newCatName, setNewCatName] = useState('');
  const [newPartner, setNewPartner] = useState({ name: '', logo: '' });
  const [newProject, setNewProject] = useState({ title: '', location: '', image: '' });

  // ID do projeto configurado no código
  const projectId = "qdigphmrabgzlbmvqqet";

  const diagnoseStorage = async () => {
    try {
      const { data, error } = await supabase.storage.listBuckets();
      if (error) {
        return `ERRO DE ACESSO: ${error.message}. Isso geralmente significa que a chave 'anon' não tem permissão de listar pastas.`;
      }
      const names = data?.map(b => b.name) || [];
      if (names.length === 0) {
        return `SISTEMA VAZIO: O Supabase retornou ZERO pastas. \n\nPROVÁVEL CAUSA: Você está logado no Supabase em um projeto diferente do projeto "${projectId}". \n\nConfira o ID na barra de endereços do seu navegador!`;
      }
      if (!names.includes('images')) {
        return `NOME INCORRETO: Pastas encontradas: ${names.join(', ')}. Nenhuma se chama "images" (minúsculo).`;
      }
      return "CONEXÃO OK: Pasta 'images' pronta para uso!";
    } catch (e: any) {
      return `ERRO FATAL: ${e.message}`;
    }
  };

  const runForceTest = async () => {
    try {
      setIsUploading(true);
      const testContent = "Teste de conexão Pindorama";
      const blob = new Blob([testContent], { type: 'text/plain' });
      const fileName = `teste-${Date.now()}.txt`;

      const { error } = await supabase.storage
        .from('images')
        .upload(`diagnostico/${fileName}`, blob);

      if (error) {
        alert(`FALHA NO TESTE REAL: ${error.message}\n\nIsso confirma que o bucket 'images' não existe ou a Policy está bloqueando o acesso.`);
      } else {
        alert("SUCESSO TOTAL! O teste de gravação funcionou. \n\nIsso significa que, embora a lista de pastas estivesse aparecendo como 'vazia', o envio de fotos vai funcionar normalmente!");
      }
    } catch (e: any) {
      alert("Erro no teste: " + e.message);
    } finally {
      setIsUploading(false);
    }
  };

  const uploadToSupabase = async (file: File): Promise<string | null> => {
    try {
      setIsUploading(true);
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random().toString(36).substring(2)}-${Date.now()}.${fileExt}`;
      const filePath = `uploads/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('images')
        .upload(filePath, file);

      if (uploadError) {
        alert(`FALHA AO SALVAR FOTO: ${uploadError.message}\n\nVerifique se criou o bucket 'images' e a Policy 'true' no Supabase.`);
        throw uploadError;
      }

      const { data } = supabase.storage.from('images').getPublicUrl(filePath);
      return data.publicUrl;
    } catch (error) {
      return null;
    } finally {
      setIsUploading(false);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
