                    <button onClick={() => props.onDeleteBanner(url)} className="absolute top-6 right-6 bg-red-500 text-white p-4 rounded-full shadow-2xl opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={24} /></button>
