import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES, PROJECTS } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory, Brand, YouTubeVideo, Project } from './types';
import { supabase, isConfigured } from './supabaseConfig';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline' | 'error'>(isConfigured ? 'offline' : 'offline');
  const [dbError, setDbError] = useState<string | null>(null);

  const [products, setProducts] = useState<Product[]>(PRODUCTS);
  const [banners, setBanners] = useState<string[]>(HERO_IMAGES);
  const [partners, setPartners] = useState<Partner[]>(PARTNERS);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [videos, setVideos] = useState<YouTubeVideo[]>([]);
  const [categories, setCategories] = useState<Category[]>(CATEGORIES.filter(c => c.id !== 'all'));
  const [projects, setProjects] = useState<Project[]>(PROJECTS);
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);

  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'Madeireira Pindorama',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@madeireirapindorama.com.br',
    address: 'Av. Guilherme Ferreira, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  const fetchData = async () => {
    if (!isConfigured) {
      setLoading(false);
      return;
    }

    try {
      const { data: settData, error: settError } = await supabase.from('settings').select('*').single();

      if (settError && settError.code !== 'PGRST116') {
        setDbStatus('error');
        setDbError(settError.message);
      } else {
        setDbStatus('online');
        if (settData) setSettings(settData);

        const { data: pData } = await supabase.from('products').select('*');
        if (pData) setProducts(pData.length > 0 ? pData : PRODUCTS);

        const { data: cData } = await supabase.from('categories').select('*');
        if (cData) setCategories(cData.length > 0 ? cData : CATEGORIES.filter(c => c.id !== 'all'));

        const { data: prtData } = await supabase.from('partners').select('*');
        if (prtData) setPartners(prtData.length > 0 ? prtData : PARTNERS);

        const { data: projData } = await supabase.from('projects').select('*');
        if (projData) setProjects(projData.length > 0 ? projData : PROJECTS);

        const { data: bnrData } = await supabase.from('banners').select('*');
        if (bnrData) setBanners(bnrData.length > 0 ? bnrData.map(b => b.image) : HERO_IMAGES);
      }
    } catch (err: any) {
      setDbStatus('error');
      setDbError(err.message || 'Erro de conexão');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleAddProduct = async (p: Product) => {
    const n = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setProducts(prev => [n, ...prev]);
    if (dbStatus === 'online') await supabase.from('products').insert(n);
  };

  const handleUpdateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    if (dbStatus === 'online') await supabase.from('products').update(p).eq('id', p.id);
  };

  const handleDeleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
    if (dbStatus === 'online') await supabase.from('products').delete().eq('id', id);
  };

  const handleAddProject = async (p: { title: string, location: string, image: string }) => {
    const n = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setProjects(prev => [n, ...prev]);
    if (dbStatus === 'online') await supabase.from('projects').insert(n);
  };

  const handleDeleteProject = async (id: string) => {
    setProjects(prev => prev.filter(p => p.id !== id));
    if (dbStatus === 'online') await supabase.from('projects').delete().eq('id', id);
  };

  const handleAddBanner = async (imageUrl: string) => {
    setBanners(prev => [...prev, imageUrl]);
    if (dbStatus === 'online') await supabase.from('banners').insert({ image: imageUrl });
  };

  const handleDeleteBanner = async (imageUrl: string) => {
    setBanners(prev => prev.filter(b => b !== imageUrl));
    if (dbStatus === 'online') await supabase.from('banners').delete().eq('image', imageUrl);
  };

  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-pindorama-green text-white">
      <div className="w-16 h-16 border-4 border-amber-600 border-t-transparent rounded-full animate-spin mb-4"></div>
      <p className="font-bold tracking-widest animate-pulse uppercase">MADEIREIRA PINDORAMA</p>
    </div>
  );

  if (isAdmin) {
    return (
      <AdminPanel 
        {...{ products, categories, subcategories, partners, brands, videos, settings, dbStatus, projects, banners }}
        dbError={dbError}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        onAddCategory={async (c) => {
          const n = { ...c, id: Math.random().toString(36) };
          setCategories(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('categories').insert(n);
        }}
        onDeleteCategory={async (id) => {
          setCategories(prev => prev.filter(c => c.id !== id));
          if (dbStatus === 'online') await supabase.from('categories').delete().eq('id', id);
        }}
        onAddPartner={async (p) => {
          const n = { ...p, id: Math.random().toString(36) };
          setPartners(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('partners').insert(n);
        }}
        onDeletePartner={async (id) => {
          setPartners(prev => prev.filter(p => p.id !== id));
          if (dbStatus === 'online') await supabase.from('partners').delete().eq('id', id);
        }}
        onAddProject={handleAddProject}
        onDeleteProject={handleDeleteProject}
        onAddBanner={handleAddBanner}
        onDeleteBanner={handleDeleteBanner}
        onAddVideo={async (v) => {
          const n = { ...v, id: Math.random().toString(36) };
          setVideos(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('videos').insert(n);
        }}
        onDeleteVideo={async (id) => {
          setVideos(prev => prev.filter(v => v.id !== id));
          if (dbStatus === 'online') await supabase.from('videos').delete().eq('id', id);
        }}
        onUpdateSettings={async (s) => {
          setSettings(s);
          if (dbStatus === 'online') await supabase.from('settings').upsert({ id: 1, ...s });
        }}
        onLogout={() => setIsAdmin(false)} 
        onAddSubcategory={async () => {}}
        onDeleteSubcategory={async () => {}}
        onAddBrand={async () => {}}
        onDeleteBrand={async () => {}}
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      <Navbar onAdminClick={() => setIsAdmin(true)} onHomeClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} />
      <Hero images={banners} />
      <About />
      <Partners partners={partners} />
      <Products products={products} categories={categories} whatsapp={settings.whatsapp} />
      <Projects projects={projects} />
      <Testimonials />
      <Footer settings={settings} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Menu, X, ShieldCheck, Home, Info, Package, Handshake, Mail, Briefcase, MessageSquare } from 'lucide-react';

interface NavbarProps {
  onAdminClick: () => void;
  onHomeClick: () => void;
  onNavLinkClick: (target: string) => void;
}

const Navbar: React.FC<NavbarProps> = ({ onAdminClick, onHomeClick, onNavLinkClick }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Início', href: '#inicio', icon: <Home size={18} /> },
    { name: 'Empresa', href: '#empresa', icon: <Info size={18} /> },
    { name: 'Parceiros', href: '#parceiros', icon: <Handshake size={18} /> },
    { name: 'Produtos', href: '#produtos', icon: <Package size={18} /> },
    { name: 'Projetos', href: '#projetos', icon: <Briefcase size={18} /> },
    { name: 'Depoimentos', href: '#depoimentos', icon: <MessageSquare size={18} /> },
    { name: 'Contato', href: '#contato', icon: <Mail size={18} /> },
  ];

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    const targetId = href.replace('#', '');
    onNavLinkClick(targetId);
    setIsOpen(false);
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-pindorama-green shadow-lg py-3' : 'bg-transparent py-5'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          <div 
            className="flex items-center cursor-pointer group"
            onClick={onHomeClick}
          >
            <div className="bg-white p-2 rounded-lg mr-3 group-hover:bg-amber-100 transition-colors">
              <ShieldCheck className="text-pindorama-green w-8 h-8" />
            </div>
            <div>
              <span className="text-white text-2xl font-bold tracking-tight block leading-none">PINDORAMA</span>
              <span className="text-amber-400 text-xs font-semibold tracking-[0.2em] uppercase">Madeireira • Uberaba</span>
            </div>
          </div>

          <div className="hidden xl:flex items-center space-x-4 lg:space-x-6">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.href}
                onClick={(e) => handleLinkClick(e, link.href)}
                className="flex items-center gap-2 text-white/90 hover:text-amber-400 font-medium text-[11px] lg:text-xs transition-colors uppercase tracking-wider group"
              >
                <span className="text-amber-500/50 group-hover:text-amber-400 transition-colors">
                  {link.icon}
                </span>
                {link.name}
              </a>
            ))}
            <button
              onClick={onAdminClick}
              className="bg-amber-600 hover:bg-amber-700 text-white px-4 py-2 rounded-full text-[11px] font-bold transition-transform hover:scale-105 shadow-lg uppercase"
            >
              Painel ADM
            </button>
          </div>

          <div className="xl:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-white hover:text-amber-400 focus:outline-none transition-colors"
            >
              {isOpen ? <X className="h-8 w-8" /> : <Menu className="h-8 w-8" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-pindorama-green border-t border-white/10 px-4 pt-4 pb-6 space-y-1 shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="flex items-center gap-4 px-4 py-3 text-white hover:bg-white/10 rounded-xl text-base font-semibold transition-all active:scale-95"
              onClick={(e) => handleLinkClick(e, link.href)}
            >
              <div className="text-amber-400">
                {link.icon}
              </div>
              {link.name}
            </a>
          ))}
          <div className="pt-4">
            <button
              onClick={() => {
                onAdminClick();
                setIsOpen(false);
              }}
              className="w-full flex items-center justify-center gap-3 bg-amber-600 text-white py-4 rounded-xl font-bold text-lg shadow-xl"
            >
              <ShieldCheck size={20} />
              Área Administrativa
            </button>
          </div>
        </div>
      )}
    </nav>
  );
};

