import React, { useState, useMemo } from 'react';
import { Product, Category, Subcategory } from '../types';
import { ShoppingCart, ChevronRight, Layers } from 'lucide-react';

interface ProductsProps {
  products: Product[];
  categories: Category[];
  subcategories: Subcategory[];
  whatsapp: string;
}

const Products: React.FC<ProductsProps> = ({ products, categories, subcategories, whatsapp }) => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [activeSubcategory, setActiveSubcategory] = useState('all');

  // Filtra categorias que possuem ao menos um produto cadastrado
  const activeCategories = useMemo(() => {
    const usedCategoryNames = new Set(products.map(p => p.category));
    return categories.filter(cat => usedCategoryNames.has(cat.name));
  }, [products, categories]);

  // Filtra subcategorias que possuem ao menos um produto cadastrado dentro da categoria selecionada
  const activeSubcategoriesForSelectedCategory = useMemo(() => {
    if (activeCategory === 'all') return [];

    const usedSubcategoryNames = new Set(
      products
        .filter(p => p.category === activeCategory)
        .map(p => p.subcategory)
    );

    return subcategories.filter(sub => 
      sub.categoryId === categories.find(c => c.name === activeCategory)?.id && 
      usedSubcategoryNames.has(sub.name)
    );
  }, [products, subcategories, activeCategory, categories]);

  const filteredProducts = useMemo(() => {
    let filtered = products;
    if (activeCategory !== 'all') {
      filtered = filtered.filter(p => p.category === activeCategory);
      if (activeSubcategory !== 'all') {
        filtered = filtered.filter(p => p.subcategory === activeSubcategory);
      }
    }
    return filtered;
  }, [products, activeCategory, activeSubcategory]);

  const handleOrder = (productName: string) => {
    const text = encodeURIComponent(`Olá, gostaria de solicitar um orçamento para: ${productName}. Vi no site de vocês.`);
    window.open(`https://wa.me/${whatsapp}?text=${text}`, '_blank');
  };

  const handleCategoryChange = (catName: string) => {
    setActiveCategory(catName);
    setActiveSubcategory('all'); // Reset subcategory when category changes
  };

  return (
    <section id="produtos" className="py-24 bg-stone-100 bg-wood-grain min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h3 className="text-amber-600 font-bold uppercase tracking-widest mb-4">Nosso Portfólio</h3>
          <h2 className="text-4xl md:text-5xl font-bold text-pindorama-green">Produtos de Excelência</h2>
          <p className="mt-6 text-stone-500 max-w-2xl mx-auto text-lg leading-relaxed">
            Selecione uma categoria abaixo para explorar nosso estoque selecionado. 
            Exibimos apenas o que temos disponível no momento.
          </p>
        </div>

        {/* Categories Selection */}
        <div className="flex flex-wrap justify-center gap-3 mb-8">
          <button
            onClick={() => handleCategoryChange('all')}
            className={`px-8 py-4 rounded-2xl text-sm font-black uppercase tracking-tighter transition-all flex items-center gap-2 ${
              activeCategory === 'all' 
                ? 'bg-pindorama-green text-white shadow-xl scale-105' 
                : 'bg-white text-pindorama-green hover:bg-stone-200 border border-stone-200'
            }`}
          >
            <Layers size={16} /> Todos os Produtos
          </button>

          {activeCategories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => handleCategoryChange(cat.name)}
              className={`px-8 py-4 rounded-2xl text-sm font-black uppercase tracking-tighter transition-all ${
                activeCategory === cat.name 
                  ? 'bg-pindorama-green text-white shadow-xl scale-105' 
                  : 'bg-white text-pindorama-green hover:bg-stone-200 border border-stone-200'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>

        {/* Subcategories Selection (Only shows if a category is selected and has subcategories with products) */}
        {activeCategory !== 'all' && activeSubcategoriesForSelectedCategory.length > 0 && (
          <div className="flex flex-wrap justify-center gap-2 mb-12 animate-fade-in">
             <div className="w-full text-center mb-4">
                <span className="text-[10px] font-black text-stone-400 uppercase tracking-[0.2em]">Filtrar por Tipo:</span>
             </div>
             <button
              onClick={() => setActiveSubcategory('all')}
