                  activeSubcategory === sub.name 
                    ? 'bg-amber-600 border-amber-600 text-white shadow-md' 
                    : 'bg-white border-stone-200 text-stone-500 hover:border-amber-500'
                }`}
              >
                {sub.name}
              </button>
            ))}
          </div>
        )}

        {/* Empty State */}
        {filteredProducts.length === 0 && (
          <div className="py-20 text-center bg-white rounded-[3rem] border-4 border-dashed border-stone-200">
             <p className="text-stone-400 font-black uppercase tracking-widest italic">Aguardando novos produtos nesta categoria...</p>
          </div>
        )}

        {/* Product Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
