                <div className="pt-6 border-t border-stone-100 mt-auto flex items-center justify-between">
                  <div>
                    <span className="text-stone-400 text-[10px] font-bold uppercase tracking-widest block mb-1">Valor Unitário</span>
                    <span className="text-2xl font-bold text-amber-700">{p.price || 'Sob consulta'}</span>
                  </div>
                  <div className="flex gap-3">
                    <button 
                      onClick={() => handleOrder(p.name)}
                      className="p-4 rounded-2xl bg-pindorama-green text-white hover:bg-black transition-all shadow-lg active:scale-90 flex items-center gap-2 group/btn"
                    >
