import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import HammerLoader from './components/HammerLoader';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES, PROJECTS } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory, Brand, YouTubeVideo, Project } from './types';
import { supabase, isConfigured } from './supabaseConfig';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showHammer, setShowHammer] = useState(false);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline' | 'error'>(isConfigured ? 'online' : 'offline');
  const [dbError, setDbError] = useState<string | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<string[]>([]);
  const [partners, setPartners] = useState<Partner[]>([]);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [videos, setVideos] = useState<YouTubeVideo[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);

  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'Madeireira Pindorama',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@madeireirapindorama.com.br',
    address: 'Av. Guilherme Ferreira, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: ''
  });

  const fetchData = async () => {
    if (!isConfigured) {
      setProducts(PRODUCTS);
      setCategories(CATEGORIES.filter(c => c.id !== 'all'));
      setPartners(PARTNERS);
      setProjects(PROJECTS);
      setBanners(HERO_IMAGES);
      setLoading(false);
      return;
    }

    try {
      const { data: settData } = await supabase.from('settings').select('*').single();
      if (settData) setSettings(settData);

      setDbStatus('online');

      const { data: pData } = await supabase.from('products').select('*');
      if (pData) setProducts(pData);

      const { data: cData } = await supabase.from('categories').select('*');
      if (cData) setCategories(cData);

      const { data: subData } = await supabase.from('subcategories').select('*');
      if (subData) setSubcategories(subData);

      const { data: prtData } = await supabase.from('partners').select('*');
      if (prtData) setPartners(prtData);

      const { data: projData } = await supabase.from('projects').select('*');
      if (projData) setProjects(projData);

      const { data: bnrData } = await supabase.from('banners').select('*');
      if (bnrData && bnrData.length > 0) {
        setBanners(bnrData.map(b => b.image));
      } else {
        setBanners(HERO_IMAGES);
      }

    } catch (err: any) {
      console.error('Erro de sincronização:', err.message);
      setDbStatus('error');
      setDbError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const triggerHammerLoader = (targetId: string) => {
    setShowHammer(true);
    setTimeout(() => {
      setShowHammer(false);
      const element = document.getElementById(targetId);
      if (element) {
        const offset = 80;
        const bodyRect = document.body.getBoundingClientRect().top;
        const elementRect = element.getBoundingClientRect().top;
        const elementPosition = elementRect - bodyRect;
        const offsetPosition = elementPosition - offset;

        window.scrollTo({
          top: offsetPosition,
          behavior: 'smooth'
        });
      }
    }, 2000);
  };

  const handleAddProduct = async (p: Product) => {
    const n = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setProducts(prev => [n, ...prev]);
    if (dbStatus === 'online') await supabase.from('products').insert(n);
  };

  const handleUpdateProduct = async (p: Product) => {
    setProducts(prev => prev.map(item => item.id === p.id ? p : item));
    if (dbStatus === 'online') await supabase.from('products').update(p).eq('id', p.id);
  };

  const handleDeleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
    if (dbStatus === 'online') await supabase.from('products').delete().eq('id', id);
  };

  const handleAddProject = async (p: { title: string, location: string, image: string }) => {
    const n = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setProjects(prev => [n, ...prev]);
    if (dbStatus === 'online') await supabase.from('projects').insert(n);
  };

  const handleDeleteProject = async (id: string) => {
    setProjects(prev => prev.filter(p => p.id !== id));
    if (dbStatus === 'online') await supabase.from('projects').delete().eq('id', id);
  };

  const handleAddBanner = async (imageUrl: string) => {
    setBanners(prev => [...prev, imageUrl]);
    if (dbStatus === 'online') await supabase.from('banners').insert({ image: imageUrl });
  };

  const handleDeleteBanner = async (imageUrl: string) => {
    setBanners(prev => prev.filter(b => b !== imageUrl));
    if (dbStatus === 'online') await supabase.from('banners').delete().eq('image', imageUrl);
  };

  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-pindorama-green text-white">
      <div className="w-16 h-16 border-4 border-amber-600 border-t-transparent rounded-full animate-spin mb-4"></div>
      <p className="font-bold tracking-widest animate-pulse uppercase">MADEIREIRA PINDORAMA</p>
    </div>
  );

  if (isAdmin) {
    return (
      <AdminPanel 
        {...{ products, categories, subcategories, partners, brands, videos, settings, dbStatus, projects, banners }}
        dbError={dbError}
        onDeleteProduct={handleDeleteProduct}
        onUpdateProduct={handleUpdateProduct}
        onAddProduct={handleAddProduct}
        onAddCategory={async (c) => {
          const n = { ...c, id: Math.random().toString(36) };
          setCategories(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('categories').insert(n);
        }}
        onDeleteCategory={async (id) => {
          setCategories(prev => prev.filter(c => c.id !== id));
          if (dbStatus === 'online') await supabase.from('categories').delete().eq('id', id);
        }}
        onAddSubcategory={async (sub) => {
          const n = { ...sub, id: Math.random().toString(36) };
          setSubcategories(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('subcategories').insert(n);
        }}
        onDeleteSubcategory={async (id) => {
          setSubcategories(prev => prev.filter(s => s.id !== id));
          if (dbStatus === 'online') await supabase.from('subcategories').delete().eq('id', id);
        }}
        onAddPartner={async (p) => {
          const n = { ...p, id: Math.random().toString(36) };
          setPartners(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('partners').insert(n);
        }}
        onDeletePartner={async (id) => {
          setPartners(prev => prev.filter(p => p.id !== id));
          if (dbStatus === 'online') await supabase.from('partners').delete().eq('id', id);
        }}
        onAddProject={handleAddProject}
        onDeleteProject={handleDeleteProject}
        onAddBanner={handleAddBanner}
        onDeleteBanner={handleDeleteBanner}
        onAddVideo={async (v) => {
          const n = { ...v, id: Math.random().toString(36) };
          setVideos(prev => [...prev, n]);
          if (dbStatus === 'online') await supabase.from('videos').insert(n);
        }}
        onDeleteVideo={async (id) => {
          setVideos(prev => prev.filter(v => v.id !== id));
          if (dbStatus === 'online') await supabase.from('videos').delete().eq('id', id);
        }}
        onUpdateSettings={async (s) => {
          setSettings(s);
          if (dbStatus === 'online') await supabase.from('settings').upsert({ id: 1, ...s });
        }}
        onLogout={() => setIsAdmin(false)} 
        onAddBrand={async () => {}}
        onDeleteBrand={async () => {}}
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50">
      {showHammer && <HammerLoader />}
      <Navbar 
        onAdminClick={() => setIsAdmin(true)} 
        onHomeClick={() => triggerHammerLoader('inicio')}
        onNavLinkClick={(target) => triggerHammerLoader(target)}
        settings={settings}
      />
      <Hero images={banners.length > 0 ? banners : HERO_IMAGES} />
      <About />
      <Partners partners={partners} />
      <Products 
        products={products} 
        categories={categories} 
        subcategories={subcategories}
        whatsapp={settings.whatsapp} 
      />
      <Projects projects={projects} />
      <Testimonials />
      <Footer settings={settings} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Product, Category, Subcategory } from '../types';
import { ShoppingCart, ChevronRight, Layers, PackageSearch } from 'lucide-react';

interface ProductsProps {
  products: Product[];
  categories: Category[];
  subcategories: Subcategory[];
  whatsapp: string;
}

const Products: React.FC<ProductsProps> = ({ products, categories, subcategories, whatsapp }) => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [activeSubcategory, setActiveSubcategory] = useState('all');

  // 1. Identifica quais categorias possuem ao menos um produto
  const categoriesWithProducts = useMemo(() => {
    const names = new Set(products.map(p => p.category).filter(Boolean));
    return categories.filter(c => names.has(c.name));
  }, [products, categories]);

  // 2. Filtra os produtos baseados na seleção
  const filteredProducts = useMemo(() => {
    if (activeCategory === 'all') return products;

    let filtered = products.filter(p => p.category === activeCategory);
    if (activeSubcategory !== 'all') {
      filtered = filtered.filter(p => p.subcategory === activeSubcategory);
    }
    return filtered;
  }, [products, activeCategory, activeSubcategory]);

  // 3. Subcategorias dinâmicas para a categoria ativa
  const subcategoriesWithProducts = useMemo(() => {
    if (activeCategory === 'all') return [];

    const usedSubNames = new Set(
      products
        .filter(p => p.category === activeCategory)
        .map(p => p.subcategory)
        .filter(Boolean)
    );

    return subcategories.filter(sub => {
      const parentCat = categories.find(c => c.id === sub.categoryId);
      return parentCat?.name === activeCategory && usedSubNames.has(sub.name);
    });
  }, [products, subcategories, activeCategory, categories]);

  const handleOrder = (productName: string) => {
    const cleanWhatsapp = whatsapp.replace(/\D/g, '');
    const text = encodeURIComponent(`Olá Pindorama, gostaria de solicitar um orçamento para: ${productName}.`);
    window.open(`https://wa.me/${cleanWhatsapp}?text=${text}`, '_blank');
  };

  if (products.length === 0) {
    return (
      <section id="produtos" className="py-24 bg-stone-100 bg-wood-grain">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <div className="bg-white p-20 rounded-[4rem] shadow-sm border-2 border-dashed border-stone-200 inline-block w-full max-w-2xl">
            <PackageSearch size={64} className="mx-auto text-stone-200 mb-6" />
            <h2 className="text-2xl font-bold text-pindorama-green mb-2 uppercase tracking-tighter italic">Catálogo em Atualização</h2>
            <p className="text-stone-400 font-bold uppercase tracking-widest text-xs italic">Estamos preparando novidades. Volte em breve!</p>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section id="produtos" className="py-24 bg-stone-100 bg-wood-grain min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h3 className="text-amber-600 font-bold uppercase tracking-widest mb-4">Produtos Disponíveis</h3>
          <h2 className="text-4xl md:text-5xl font-bold text-pindorama-green font-serif italic">Tradição em cada detalhe</h2>
        </div>

        {/* Filtros de Categorias (Só aparecem se houver mais de uma categoria com produtos) */}
        {categoriesWithProducts.length > 0 && (
          <div className="flex flex-wrap justify-center gap-3 mb-10">
            <button
              onClick={() => { setActiveCategory('all'); setActiveSubcategory('all'); }}
              className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-tighter transition-all flex items-center gap-2 ${
                activeCategory === 'all' 
                  ? 'bg-pindorama-green text-white shadow-xl scale-105' 
                  : 'bg-white text-pindorama-green hover:bg-stone-200 border border-stone-200'
              }`}
            >
              <Layers size={14} /> Todos os Itens
            </button>

            {categoriesWithProducts.map((cat) => (
              <button
                key={cat.id}
                onClick={() => { setActiveCategory(cat.name); setActiveSubcategory('all'); }}
                className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-tighter transition-all ${
                  activeCategory === cat.name 
                    ? 'bg-pindorama-green text-white shadow-xl scale-105' 
                    : 'bg-white text-pindorama-green hover:bg-stone-200 border border-stone-200'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        )}

        {/* Subcategorias */}
        {activeCategory !== 'all' && subcategoriesWithProducts.length > 0 && (
          <div className="flex flex-wrap justify-center gap-2 mb-12 animate-fade-in">
            <button
              onClick={() => setActiveSubcategory('all')}
              className={`px-6 py-2 rounded-full text-[10px] font-black uppercase transition-all border ${
                activeSubcategory === 'all' 
                  ? 'bg-amber-600 border-amber-600 text-white shadow-md' 
                  : 'bg-white border-stone-200 text-stone-500'
              }`}
            >
              Ver Todas as Variedades
            </button>
            {subcategoriesWithProducts.map((sub) => (
              <button
                key={sub.id}
                onClick={() => setActiveSubcategory(sub.name)}
                className={`px-6 py-2 rounded-full text-[10px] font-black uppercase transition-all border ${
                  activeSubcategory === sub.name 
                    ? 'bg-amber-600 border-amber-600 text-white shadow-md' 
                    : 'bg-white border-stone-200 text-stone-500'
                }`}
              >
                {sub.name}
              </button>
            ))}
          </div>
        )}

        {/* Lista de Produtos */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
          {filteredProducts.map((p) => (
            <div key={p.id} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl hover:shadow-2xl transition-all group border border-stone-100 flex flex-col hover:-translate-y-2">
              <div className="h-72 overflow-hidden relative">
                <img 
                  src={p.image || 'https://images.unsplash.com/photo-1588508065123-287b28e013da?auto=format&fit=crop&q=80&w=600'} 
                  alt={p.name} 
                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                />
                <div className="absolute top-6 left-6 flex flex-col gap-2">
                   {p.category && (
                     <div className="bg-pindorama-green text-white text-[9px] font-black px-4 py-2 rounded-full shadow-lg backdrop-blur-md uppercase tracking-wider">
                      {p.category}
                    </div>
                   )}
                  {p.subcategory && (
                    <div className="bg-amber-600 text-white text-[8px] font-black px-3 py-1.5 rounded-full shadow-lg backdrop-blur-md uppercase tracking-wider flex items-center gap-1 self-start">
                      <ChevronRight size={10} /> {p.subcategory}
                    </div>
                  )}
                </div>
              </div>
              <div className="p-10 flex-1 flex flex-col">
                <h4 className="text-2xl font-bold text-pindorama-green mb-4">{p.name}</h4>
                <p className="text-stone-500 mb-8 line-clamp-3 flex-1 text-sm leading-relaxed">{p.description}</p>

                <div className="pt-6 border-t border-stone-100 mt-auto flex items-center justify-between">
                  <div>
                    <span className="text-stone-400 text-[10px] font-bold uppercase tracking-widest block mb-1">Cotação</span>
                    <span className="text-xl font-bold text-amber-700">{p.price || 'Sob consulta'}</span>
                  </div>
                  <button 
                    onClick={() => handleOrder(p.name)}
                    className="p-4 rounded-2xl bg-pindorama-green text-white hover:bg-black transition-all shadow-lg active:scale-90"
                  >
                    <ShoppingCart size={20} />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

