        .from('images')
        .upload(filePath, file);

      if (uploadError) {
        alert(`FALHA AO SALVAR FOTO: ${uploadError.message}`);
        throw uploadError;
      }

      const { data } = supabase.storage.from('images').getPublicUrl(filePath);
