              >
                <Plus size={20} /> Nova Madeira
              </button>
            )}
          </div>

          {/* Aba Ajustes do Site (Identidade) */}
          {activeTab === 'settings' && (
            <div className="space-y-8 pb-20">
               <div className="bg-white p-12 rounded-[3.5rem] shadow-sm border border-stone-200">
