                     <label className="block space-y-2">
                        <span className="text-[10px] font-black uppercase text-stone-400 ml-2">Telefone Fixo</span>
                        <input type="text" value={localSettings.phone} onChange={e => setLocalSettings({...localSettings, phone: e.target.value})} className="w-full px-6 py-4 bg-stone-50 rounded-xl font-bold" />
                     </label>
                     <label className="block md:col-span-2 space-y-2">
                        <span className="text-[10px] font-black uppercase text-stone-400 ml-2">Endereço Uberaba</span>
                        <input type="text" value={localSettings.address} onChange={e => setLocalSettings({...localSettings, address: e.target.value})} className="w-full px-6 py-4 bg-stone-50 rounded-xl font-bold" />
                     </label>
                  </div>
               </div>
               <div className="flex justify-end">
                  <button onClick={() => props.onUpdateSettings(localSettings)} className="bg-pindorama-green text-white px-12 py-5 rounded-2xl font-black text-sm uppercase shadow-xl flex items-center gap-3">
                     <Save size={20} /> Salvar Identidade do Site
                  </button>
               </div>
            </div>
          )}

          {activeTab === 'partners' && (
            <div className="space-y-10">
               <div className="bg-white p-10 rounded-3xl border border-stone-200">
                  <h3 className="text-xl font-black text-pindorama-green mb-6 uppercase">Adicionar Novo Parceiro</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <input type="text" placeholder="Nome da Marca" value={newPartner.name} onChange={e => setNewPartner({...newPartner, name: e.target.value})} className="px-6 py-4 bg-stone-50 rounded-xl font-bold" />
                     <div className="flex gap-4">
                        <input type="text" placeholder="URL da Logo" value={newPartner.logo} onChange={e => setNewPartner({...newPartner, logo: e.target.value})} className="flex-1 px-6 py-4 bg-stone-50 rounded-xl font-bold" />
                        <button onClick={() => { props.onAddPartner(newPartner); setNewPartner({name: '', logo: ''}); }} className="bg-amber-600 text-white px-8 rounded-xl font-black uppercase text-[10px]">Gravar</button>
                     </div>
                  </div>
               </div>
               <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6">
                  {props.partners.map(p => (
                    <div key={p.id} className="bg-white p-6 rounded-3xl border border-stone-200 text-center relative group">
                       <img src={p.logo} className="h-12 mx-auto object-contain mb-4" />
                       <p className="text-[10px] font-black uppercase text-stone-400">{p.name}</p>
                       <button onClick={() => props.onDeletePartner(p.id)} className="absolute -top-2 -right-2 bg-red-500 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={12} /></button>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {activeTab === 'banners' && (
            <div className="space-y-10">
               <div className="bg-white p-10 rounded-3xl border border-stone-200">
                  <h3 className="text-xl font-black text-pindorama-green mb-6 uppercase">Adicionar Slide ao Topo</h3>
                  <div className="flex gap-4">
                     <input type="text" placeholder="URL da Imagem de Fundo (Grande)" value={newBannerUrl} onChange={e => setNewBannerUrl(e.target.value)} className="flex-1 px-6 py-4 bg-stone-50 rounded-xl font-bold" />
                     <button onClick={() => { props.onAddBanner(newBannerUrl); setNewBannerUrl(''); }} className="bg-amber-600 text-white px-10 rounded-xl font-black uppercase text-[10px]">Adicionar</button>
                  </div>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {props.banners.map((url, i) => (
                    <div key={i} className="bg-white h-40 rounded-3xl border border-stone-200 overflow-hidden relative group">
                       <img src={url} className="w-full h-full object-cover" />
                       <button onClick={() => props.onDeleteBanner(url)} className="absolute inset-0 bg-red-500/80 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center font-black uppercase text-xs">Excluir Slide</button>
                    </div>
                  ))}
               </div>
            </div>
          )}
        </div>
      </main>

      {editingProduct && (
        <div className="fixed inset-0 bg-stone-900/90 z-[150] flex items-center justify-center p-6">
          <div className="bg-white rounded-[3rem] w-full max-w-xl p-10">
            <h3 className="text-2xl font-black text-pindorama-green uppercase mb-8">Ficha da Madeira</h3>
            <div className="space-y-6">
               <input type="text" placeholder="Nome do Produto" value={editingProduct.name} onChange={e => setEditingProduct({...editingProduct, name: e.target.value})} className="w-full px-6 py-4 bg-stone-50 rounded-xl font-bold" />
               <select value={editingProduct.category} onChange={e => setEditingProduct({...editingProduct, category: e.target.value})} className="w-full px-6 py-4 bg-stone-50 rounded-xl font-bold">
                  {props.categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
               </select>
               <div className="bg-stone-50 p-6 rounded-xl border-2 border-dashed border-stone-200 text-center">
                  {editingProduct.image ? <img src={editingProduct.image} className="w-32 h-32 mx-auto rounded-xl object-cover mb-4" /> : <Camera size={32} className="mx-auto text-stone-300 mb-4" />}
                  <label className="bg-pindorama-green text-white px-6 py-3 rounded-lg text-xs font-black uppercase cursor-pointer">
                     {isUploading ? 'Subindo...' : 'Selecionar Foto'}
                     <input type="file" className="hidden" onChange={async e => {
                        const file = e.target.files?.[0];
                        if (file) {
                          const url = await uploadToSupabase(file);
                          if (url) setEditingProduct({...editingProduct, image: url});
                        }
                     }} />
                  </label>
               </div>
               <textarea placeholder="Descrição curta" value={editingProduct.description} onChange={e => setEditingProduct({...editingProduct, description: e.target.value})} className="w-full px-6 py-4 bg-stone-50 rounded-xl font-bold" />
               <div className="flex gap-4">
                  <button onClick={() => { 
                    setIsSaving(true);
                    const action = editingProduct.id.startsWith('new-') ? props.onAddProduct(editingProduct) : props.onUpdateProduct(editingProduct);
                    action.then(() => { setIsSaving(false); setEditingProduct(null); });
                  }} className="flex-1 bg-amber-600 text-white py-4 rounded-xl font-black uppercase text-xs">Salvar Madeira</button>
                  <button onClick={() => setEditingProduct(null)} className="flex-1 bg-stone-100 py-4 rounded-xl font-black uppercase text-xs">Cancelar</button>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Products from './components/Products';
import Partners from './components/Partners';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import AdminPanel from './components/AdminPanel';
import HammerLoader from './components/HammerLoader';
import { PRODUCTS, HERO_IMAGES, PARTNERS, CATEGORIES, PROJECTS } from './constants';
import { Product, Partner, SiteSettings, Category, Subcategory, Brand, YouTubeVideo, Project } from './types';
import { supabase, isConfigured } from './supabaseConfig';
import { ShieldCheck } from 'lucide-react';

const App: React.FC = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showHammer, setShowHammer] = useState(false);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline' | 'error'>(isConfigured ? 'online' : 'offline');
  const [dbError, setDbError] = useState<string | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<string[]>([]);
  const [partners, setPartners] = useState<Partner[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);

  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'Madeireira Pindorama',
    phone: '(34) 3333-3333',
    whatsapp: '5534999999999',
    email: 'contato@madeireirapindorama.com.br',
    address: 'Av. Guilherme Ferreira, Uberaba - MG',
    hoursWeek: '08:00 - 18:00',
    hoursSat: '08:00 - 12:00',
    instagram: 'https://instagram.com/madeireirapindorama',
    facebook: 'https://facebook.com/madeireirapindorama',
    pixelId: '',
    googleTag: '',
    aboutTitle: 'A Tradição que Solidifica Uberaba.',
    aboutText: 'Nascemos no coração do Triângulo Mineiro com uma promessa: oferecer madeira que resiste ao tempo. Hoje, 45 anos depois, a Madeireira Pindorama não apenas vende matéria-prima, mas fornece a base para os sonhos de milhares de famílias.',
    mission: 'Prover soluções em madeira de alta qualidade, auxiliando no desenvolvimento sustentável da construção civil.',
    vision: 'Ser referência absoluta em Uberaba e no Triângulo Mineiro como a madeireira mais confiável e completa.',
    principles: 'Integridade em cada venda, respeito ao meio ambiente e foco total na satisfação do cliente.',
    valuesText: 'Tradição, Qualidade, Pontualidade na entrega e Ética Comercial fundamentada em nossa história.'
  });

  const fetchData = async () => {
    if (!isConfigured) {
      setProducts(PRODUCTS);
      setCategories(CATEGORIES.filter(c => c.id !== 'all'));
      setPartners(PARTNERS);
      setProjects(PROJECTS);
      setBanners(HERO_IMAGES);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);

      const { data: settData } = await supabase.from('settings').select('*').single();
      if (settData) setSettings(prev => ({ ...prev, ...settData }));

      const { data: pData } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (pData && pData.length > 0) setProducts(pData);
      else setProducts(PRODUCTS);

      const { data: cData } = await supabase.from('categories').select('*');
      if (cData && cData.length > 0) setCategories(cData);
      else setCategories(CATEGORIES.filter(c => c.id !== 'all'));

      const { data: subData } = await supabase.from('subcategories').select('*');
      if (subData) setSubcategories(subData);

      const { data: prtData } = await supabase.from('partners').select('*');
      if (prtData && prtData.length > 0) setPartners(prtData);
      else setPartners(PARTNERS);

      const { data: projData } = await supabase.from('projects').select('*').order('created_at', { ascending: false });
      if (projData && projData.length > 0) setProjects(projData);
      else setProjects(PROJECTS);

      const { data: bnrData } = await supabase.from('banners').select('*');
      if (bnrData && bnrData.length > 0) {
        setBanners(bnrData.map(b => b.image));
      } else {
        setBanners(HERO_IMAGES);
      }

      setDbStatus('online');
    } catch (err: any) {
      console.error('Erro de sincronização:', err.message);
      setDbStatus('error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleUpdateSettings = async (s: SiteSettings) => {
    try {
      if (isConfigured) {
        const { error } = await supabase.from('settings').upsert({ id: 1, ...s });
        if (error) throw error;
      }
      setSettings(s);
      alert("Alterações salvas com sucesso!");
    } catch (err: any) {
      alert(`Erro ao salvar: ${err.message}`);
    }
  };

  const triggerHammerLoader = (targetId: string) => {
    setShowHammer(true);
    setTimeout(() => {
      setShowHammer(false);
      const element = document.getElementById(targetId);
      if (element) {
        window.scrollTo({ top: element.offsetTop - 80, behavior: 'smooth' });
      }
    }, 1500);
  };

  if (loading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-pindorama-green text-white">
      <div className="w-16 h-16 border-4 border-amber-600 border-t-transparent rounded-full animate-spin mb-4"></div>
      <p className="font-black uppercase tracking-widest">Carregando Madeireira Pindorama...</p>
    </div>
  );

  if (isAdmin) {
    return (
      <AdminPanel 
        {...{ products, categories, subcategories, partners, settings, dbStatus, projects, banners }}
        onDeleteProduct={async (id) => {
          if (isConfigured) await supabase.from('products').delete().eq('id', id);
          setProducts(prev => prev.filter(p => p.id !== id));
        }}
        onUpdateProduct={async (p) => {
          if (isConfigured) await supabase.from('products').update(p).eq('id', p.id);
          setProducts(prev => prev.map(item => item.id === p.id ? p : item));
        }}
        onAddProduct={async (p) => {
          const n = { ...p, id: Math.random().toString(36).substr(2, 9), created_at: new Date() };
          if (isConfigured) await supabase.from('products').insert(n);
          setProducts(prev => [n, ...prev]);
        }}
        onAddCategory={async (c) => {
          const n = { ...c, id: Math.random().toString(36).substr(2, 9) };
          if (isConfigured) await supabase.from('categories').insert(n);
          setCategories(prev => [...prev, n]);
        }}
        onDeleteCategory={async (id) => {
          if (isConfigured) await supabase.from('categories').delete().eq('id', id);
          setCategories(prev => prev.filter(c => c.id !== id));
        }}
        onAddSubcategory={async (sub) => {
          const n = { ...sub, id: Math.random().toString(36) };
          if (isConfigured) await supabase.from('subcategories').insert(n);
          setSubcategories(prev => [...prev, n]);
        }}
        onDeleteSubcategory={async (id) => {
          if (isConfigured) await supabase.from('subcategories').delete().eq('id', id);
          setSubcategories(prev => prev.filter(s => s.id !== id));
        }}
        onAddPartner={async (p) => {
          const n = { ...p, id: Math.random().toString(36) };
          if (isConfigured) await supabase.from('partners').insert(n);
          setPartners(prev => [...prev, n]);
        }}
        onDeletePartner={async (id) => {
          if (isConfigured) await supabase.from('partners').delete().eq('id', id);
          setPartners(prev => prev.filter(p => p.id !== id));
        }}
        onAddProject={async (p) => {
          const n = { ...p, id: Math.random().toString(36), created_at: new Date() };
          if (isConfigured) await supabase.from('projects').insert(n);
          setProjects(prev => [n, ...prev]);
        }}
        onDeleteProject={async (id) => {
          if (isConfigured) await supabase.from('projects').delete().eq('id', id);
          setProjects(prev => prev.filter(p => p.id !== id));
        }}
        onAddBanner={async (url) => {
          if (isConfigured) await supabase.from('banners').insert({ image: url });
          setBanners(prev => [...prev, url]);
        }}
        onDeleteBanner={async (url) => {
          if (isConfigured) await supabase.from('banners').delete().eq('image', url);
          setBanners(prev => prev.filter(b => b !== url));
        }}
        onUpdateSettings={handleUpdateSettings}
        onLogout={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-stone-50 overflow-x-hidden">
      {showHammer && <HammerLoader />}
      <Navbar 
        onAdminClick={() => setIsAdmin(true)} 
        onHomeClick={() => triggerHammerLoader('inicio')}
        onNavLinkClick={(target) => triggerHammerLoader(target)}
        settings={settings}
      />
      <Hero images={banners.length > 0 ? banners : HERO_IMAGES} settings={settings} />
      <About settings={settings} />
      <Partners partners={partners} />
      <Products 
        products={products} 
        categories={categories} 
        subcategories={subcategories}
        whatsapp={settings.whatsapp} 
      />
      <Projects projects={projects} />
      <Testimonials />
      <Footer settings={settings} />
    </div>
  );
};

export default App;
